"use strict";
const fs = require("node:fs");
const path = require("node:path");
const cp = require("node:child_process");
const crypto = require("node:crypto");
const root = __dirname;
const program = `import json,sys
from datetime import datetime,timedelta
d=json.load(sys.stdin)
sys.path.insert(0,d["support"])
ns={"__name__":"more_itertools.more","__package__":"more_itertools","__file__":"<frozen-source>"}
exec(compile(d["source"],"<frozen-source>","exec"),ns)
rows=[]
for start,stop,step in [(datetime.max-timedelta(days=1),datetime.max,timedelta(days=2)),(datetime.min+timedelta(days=1),datetime.min,-timedelta(days=2))]:
    try:
        n=len(ns["numeric_range"](start,stop,step))
        rows.append({"passed":n==1,"length":n})
    except Exception as e:
        rows.append({"passed":False,"exception":type(e).__name__,"message":str(e)})
print(json.dumps(rows))
`;
const parent = cp.execFileSync("git", ["show", "2fe1b2eeb9d75f994113fe3ac76d14b6bcd6fb10:more_itertools/more.py"], { cwd: path.join(root, "repos/more-itertools"), encoding: "utf8" });
const candidate = fs.readFileSync(path.join(root, "trials/more-itertools-1247--gpt-fixed--r1/runs/more-itertools-1247/gpt-fixed-r1/more_itertools/more.py"), "utf8");
const results = [{ version: "parent", source: parent }, { version: "582ab48-r1", source: candidate }].map(({ version, source }) => {
  const p = cp.spawnSync(path.join(root, "venvs/more-itertools/bin/python"), ["-B", "-c", program], { input: JSON.stringify({ source, support: path.join(root, "validation/more-itertools-1247/checkout") }), encoding: "utf8", timeout: 2000, env: { ...process.env, PYTHONDONTWRITEBYTECODE: "1" } });
  if (p.status !== 0) throw new Error(p.stderr || String(p.error));
  return { version, source_sha256: crypto.createHash("sha256").update(source).digest("hex"), cases: JSON.parse(p.stdout) };
});
const report = { kind: "Exploratory diagnosis during measured trials after static inspection; original artifact unchanged, no new model, does not replace final uniform probes", recorded_at: new Date().toISOString(), program, source: fs.readFileSync(__filename, "utf8"), results };
fs.writeFileSync(path.join(root, "exploratory-date-regression.json"), JSON.stringify(report, null, 2));
console.log(JSON.stringify(results));
